import { waitUntil } from 'next/server';

interface PageViewEvent {
  path: string;
  timestamp: string;
  userAgent?: string;
}

async function logPageView(event: PageViewEvent): Promise<void> {
  const endpoint = process.env.ANALYTICS_ENDPOINT || 'https://analytics.example.com/log';

  try {
    await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(event),
    });
  } catch (error) {
    console.error('Failed to log page view:', error);
  }
}

export default function HomePage({ searchParams }: { searchParams: Promise<{ [key: string]: string | string[] | undefined }> }) {
  const resolvedSearchParams = searchParams;
  const pagePath = '/';
  const userAgent = 'server';

  waitUntil(logPageView({
    path: pagePath,
    timestamp: new Date().toISOString(),
    userAgent,
  }));

  return (
    <main>
      <h1>Welcome to Our Application</h1>
      <p>This is a server component with non-blocking analytics logging.</p>
    </main>
  );
}

